messages.content:
Tool response:
Tool: create_event_type
Description: Create Event Type
Parameters:
    {
      "type": "object",
      "properties": {
        "name": {
          "type": "string",
          "title": "Name"
        },
        "duration_minutes": {
          "type": "integer",
          "title": "Duration Minutes"
        },
        "location": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Location"
        },
        "availability_synced_to_google_calendar": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "title": "Availability Synced To Google Calendar"
        },
        "buffer_before_minutes": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "title": "Buffer Before Minutes"
        },
        "buffer_after_minutes": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "title": "Buffer After Minutes"
        },
        "max_bookings_per_day": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "title": "Max Bookings Per Day"
        },
        "custom_questions": {
          "anyOf": [
            {
              "items": {
                "properties": {
                  "question_text": {
                    "type": "string",
                    "title": "Question Text"
                  },
                  "question_type": {
                    "type": "string",
                    "title": "Question Type"
                  },
                  "is_required": {
                    "type": "boolean",
                    "title": "Is Required",
                    "default": false
                  }
                },
                "type": "object",
                "required": [
                  "question_text",
                  "question_type"
                ],
                "title": "CustomQuestion"
              },
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "title": "Custom Questions"
        }
      },
      "required": [
        "name",
        "duration_minutes"
      ]
    }
